package com.yuegang.zhihui.notification.application;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.context.annotation.*;
@Configuration(proxyBeanMethods=false)@ConditionalOnProperty(name="ygh.mq.enabled",havingValue="true")class NotificationMqConfiguration{@Bean(destroyMethod="close")NotificationDomainEventConsumer notificationDomainEventConsumer(@Value("${ygh.mq.nameserver}")String n,@Value("${ygh.mq.topic:YGH_DOMAIN_EVENTS}")String t,NotificationService s,ObjectMapper j){return new NotificationDomainEventConsumer(n,t,s,j);}}
